declare(strict_types=1);

class Book
{
    private int $id;
    private string $title;
    private string $author;
    private string $isbn;
    private int $stock;
    private int $total;

    public function __construct(
        int $id,
        string $title,
        string $author,
        string $isbn,
        int $stock,
        int $total
    ) {
        $this->id = $id;
        $this->title = $title;
        $this->author = $author;
        $this->isbn = $isbn;
        $this->stock = $stock;
        $this->total = $total;
    }

    // getters -------------------------------------------------
    public function getId(): int { return $this->id; }
    public function getTitle(): string { return $this->title; }
    public function getAuthor(): string { return $this->author; }
    public function getIsbn(): string { return $this->isbn; }
    public function getStock(): int { return $this->stock; }
    public function getTotal(): int { return $this->total; }

    // static CRUD ---------------------------------------------
    public static function findById(int $id, PDO $pdo): ?self
    {
        $stmt = $pdo->prepare('SELECT id, title, author, isbn, stock, total FROM books WHERE id = :id');
        $stmt->execute(['id' => $id]);
        $row = $stmt->fetch();
        return $row ? new self($row['id'], $row['title'], $row['author'], $row['isbn'],
                               $row['stock'], $row['total']) : null;
    }

    public static function findByIsbn(string $isbn, PDO $pdo): ?self
    {
        $stmt = $pdo->prepare('SELECT id, title, author, isbn, stock, total FROM books WHERE isbn = :isbn');
        $stmt->execute(['isbn' => $isbn]);
        $row = $stmt->fetch();
        return $row ? new self($row['id'], $row['title'], $row['author'], $row['isbn'],
                               $row['stock'], $row['total']) : null;
    }

    public static function create(array $data, PDO $pdo): ?self
    {
        $stmt = $pdo->prepare('INSERT INTO books (title, author, isbn, stock, total) 
                              VALUES (:title, :author, :isbn, :stock, :total)');
        $stmt->execute([
            'title'  => $data['title'],
            'author' => $data['author'],
            'isbn'   => $data['isbn'],
            'stock'  => $data['stock'] ?? 0,
            'total'  => $data['total'] ?? 0,
        ]);
        $id = (int)$pdo->lastInsertId();
        return new self($id, $data['title'], $data['author'], $data['isbn'],
                        $data['stock'] ?? 0, $data['total'] ?? 0);
    }

    // 在庫増減（入庫・出庫） ------------------------------------
    public function increaseStock(int $qty, PDO $pdo): void
    {
        $stmt = $pdo->prepare('UPDATE books SET stock = stock + :qty, total = total + :qty WHERE id = :id');
        $stmt->execute(['qty' => $qty, 'id' => $this->id]);
    }

    public function decreaseStock(int $qty, PDO $pdo): void
    {
        $stmt = $pdo->prepare('UPDATE books SET stock = stock - :qty, total = total - :qty WHERE id = :id');
        $stmt->execute(['qty' => $qty, 'id' => $this->id]);
    }
}
?>
